def mesh_matrix_from_mesh_data(mesh_data):
    """The source transform carried by a geometry-DATA MObject, as a flat
    row-major 16-tuple (Maya's row-vector convention: translation in [12:15]).
    Returns None when the data is missing or unreadable. Never raises.

    ``worldMesh[0]`` DATA holds OBJECT-space points plus this matrix; it does
    NOT hold baked world points. A function set built from a data MObject has no
    DAG path, so ``getPoints(kWorld)`` cannot reach world space -- ``p * M`` with
    this matrix is the only way, and it reproduces ``MFnMesh(dagPath).getPoints(
    kWorld)`` exactly. A draw that reads a mesh input and claims world space is
    pinned at the origin without it.

    Same dual-MObject dispatch as :func:`tag_indices_from_mesh_data`: api2 from
    the plug side-channel, api1 from the EM-safe datablock path."""
    if mesh_data is None:
        return None
    try:
        import maya.api.OpenMaya as om2

        if isinstance(mesh_data, om2.MObject):
            return tuple(om2.MFnGeometryData(mesh_data).matrix)
    except Exception:
        pass
    try:
        import maya.OpenMaya as om1

        # api1 mirrors C++: getMatrix(MMatrix&) out-param, NOT the api2
        # ``.matrix`` property. This is the branch the LIVE compute takes --
        # mesh_data_from_node_plug hands back an api1 MObject.
        m = om1.MMatrix()
        om1.MFnGeometryData(mesh_data).getMatrix(m)
        return tuple(m(r, c) for r in range(4) for c in range(4))
    except Exception:
        return None

def node_name_from_self(self_proxy) -> str:
    """Recover the owning node's name from an Init (InitProxy) or Compute
    (SelfProxy) ``self`` object, since neither exposes a public accessor.
    Returns "" if it can't be determined."""
    # Init phase: InitProxy stashes the node name.
    try:
        return object.__getattribute__(self_proxy, "_ip_node_name")
    except AttributeError:
        pass
    # Compute phase: SelfProxy stashes the (api1) MObject.
    try:
        import maya.OpenMaya as om1

        mobj = object.__getattribute__(self_proxy, "_psp_mobject")
        return om1.MFnDependencyNode(mobj).name()
    except Exception:
        return ""

class DrawItem:
    """Base for every drawable. Carries colour + space, composition via ``+``,
    and the chainable transform/restyle methods (each returns a NEW item, so a
    drawing you built once can be reused at several transforms)."""

    _SLOT = None                 # which draw buffer this flushes into
    _POINT_FIELDS = ()           # attributes holding (N,3) arrays

    # numpy must defer to __radd__ instead of broadcasting us into an array
    __array_ufunc__ = None

    def __init__(self, color=None, space="local", screen_space=False):
        self._color = color
        self._space = "screen" if screen_space else normalize_space(space)

    # ----- composition -----
    def __add__(self, other):
        if not isinstance(other, DrawItem):
            raise TypeError(
                "can only add draw items together, not %s -- '+' groups "
                "drawables, it is not arithmetic" % type(other).__name__)
        return DrawGroup(self._as_list() + other._as_list())

    def __radd__(self, other):
        if isinstance(other, int) and other == 0:      # sum([...])
            return DrawGroup(self._as_list())
        return self.__add__(other)

    def _as_list(self):
        return [self]

    # `*` and `-` are deliberately absent: see the module docstring.

    # ----- chainable transforms / restyle -----
    def _mutated(self):
        return _copy.copy(self)

    def colored(self, color):
        """A copy drawn in ``color`` (RGB or RGBA, uniform or per-element)."""
        out = self._mutated()
        out._color = color
        return out

    def in_space(self, space):
        """A copy drawn in ``"local"`` (object space) or ``"screen"`` (pixels)."""
        out = self._mutated()
        out._space = normalize_space(space)
        return out

    def translated(self, x, y=None, z=None):
        """A copy moved by a vector (``translated(v)`` or ``translated(x,y,z)``)."""
        off = np.asarray((x, y, z) if y is not None else x,
                         dtype=np.float64).ravel()
        if off.size != 3:
            raise ValueError("translated: expected 3 components")
        out = self._mutated()
        for f in self._POINT_FIELDS:
            setattr(out, f, getattr(self, f) + off)
        return out

    def scaled(self, factor):
        """A copy scaled about the origin. Subclasses also scale their radii /
        glyph sizes so a scaled drawing stays proportional."""
        s = float(factor)
        out = self._mutated()
        for f in self._POINT_FIELDS:
            setattr(out, f, getattr(self, f) * s)
        return out

    # ----- flush -----
    def to_commands(self):
        """The ordered draw-command list, exactly as
        ``MPyLocator.evaluateDrawItems`` harvests it."""
        return to_commands(self)

    # ----- serialization -----
    # Draw items are plain objects over numpy arrays, so ``pickle`` already
    # round-trips them; JSON is the portable form (no numpy, no Python types)
    # for shipping a drawing between processes or storing it in a file.
    def to_json(self):
        """A plain-JSON dict describing this item (recursive for a group)."""
        return {"type": type(self).__name__,
                "state": {k: _json_value(v) for k, v in self.__dict__.items()}}

    @classmethod
    def from_json(cls, payload):
        """Rebuild a drawing from :meth:`to_json` output (dict, list, or text)."""
        return draw_from_json(payload)

    def __repr__(self):
        return "<%s slot=%s space=%s>" % (
            type(self).__name__, self._SLOT, self._space)

def _points(value, what="points"):
    """``(N,3)`` float64. A bare ``(3,)`` is promoted to a single row so one
    circle costs one tuple instead of a nested one-element array."""
    a = np.asarray(value, dtype=np.float64)
    if a.ndim == 1:
        if a.size != 3:
            raise ValueError("%s: a single point needs 3 components, got %d"
                             % (what, a.size))
        return a.reshape(1, 3)
    if a.ndim == 2 and a.shape[1] == 3:
        return a
    if a.ndim == 2 and a.shape[1] == 2:          # 2D convenience, pad z=0
        pad = np.zeros((a.shape[0], 3), dtype=np.float64)
        pad[:, :2] = a
        return pad
    raise ValueError("%s: expected (N,3), got %s" % (what, (a.shape,)))

def mesh_vertex_normals(mesh, space=None):
    """Return ``(V, 3)`` unit per-vertex normals (Maya's averaged vertex
    normals) for an ``MFnMesh``, aligned with ``mesh_arrays`` point order.

    Use these to push a region off the surface along its own normals (kills
    Z-fighting) or to drive a normal-aligned pop animation. API 2.0 is
    vectorized; API 1.0 falls back to a small loop.
    """
    if not _is_api2(mesh):
        n = _normals_api1(mesh, space)
    else:
        if space is None:
            space = om.MSpace.kObject
        n = np.asarray(mesh.getVertexNormals(False, space))[:, :3].astype(np.float64)
    # Defensive renormalize (Maya returns unit normals, but guard zeros).
    mag = np.linalg.norm(n, axis=1, keepdims=True)
    return n / np.where(mag > 1e-12, mag, 1.0)

class DrawGroup(DrawItem):
    """What ``+`` returns: a flat list of drawables sharing one flush."""

    _SLOT = None

    def __init__(self, items=()):
        DrawItem.__init__(self)
        self._items = list(items)

    def _as_list(self):
        return list(self._items)

    def __len__(self):
        return len(self._items)

    def __iter__(self):
        return iter(self._items)

    def _mutated(self):
        out = _copy.copy(self)
        out._items = list(self._items)
        return out

    def colored(self, color):
        out = self._mutated()
        out._items = [i.colored(color) for i in self._items]
        return out

    def in_space(self, space):
        out = self._mutated()
        out._items = [i.in_space(space) for i in self._items]
        return out

    def translated(self, x, y=None, z=None):
        out = self._mutated()
        out._items = [i.translated(x, y, z) for i in self._items]
        return out

    def scaled(self, factor):
        out = self._mutated()
        out._items = [i.scaled(factor) for i in self._items]
        return out

    def __repr__(self):
        return "<DrawGroup %d items>" % len(self._items)

def _json_value(v):
    """One state value as JSON-safe data."""
    if isinstance(v, np.ndarray):
        return {"__ndarray__": v.tolist(), "dtype": str(v.dtype)}
    if isinstance(v, DrawItem):
        return v.to_json()
    if isinstance(v, (list, tuple)):
        return [_json_value(x) for x in v]
    if isinstance(v, dict):
        return {k: _json_value(x) for k, x in v.items()}
    if isinstance(v, (np.floating, np.integer, np.bool_)):
        return v.item()
    return v

def _json_revive(v):
    """Inverse of :func:`_json_value`."""
    if isinstance(v, dict):
        if "__ndarray__" in v:
            return np.asarray(v["__ndarray__"], dtype=np.dtype(v["dtype"]))
        if "type" in v and "state" in v:
            return draw_from_json(v)
        return {k: _json_revive(x) for k, x in v.items()}
    if isinstance(v, list):
        return [_json_revive(x) for x in v]
    return v
